}

var nodeId = inputData.id || "unknown";

// --- 2. FILTRO DE SEGURIDAD ---
var validSensors = ["Dango_Node_001", "Dango_Node_002", "Telescopio_01", "Industria_SRO", "Industria_Node_01"]; 
