    // Procesar S1
    if (buf.s1_ax.length > 0) {
        var mX = calculateComplexMetrics(buf.s1_ax, duration);
        var mY = calculateComplexMetrics(buf.s1_ay, duration);
        var mZ = calculateComplexMetrics(buf.s1_az, duration);

        // Magnitud vectorial de la velocidad
        var vel_mag = Math.sqrt(mX.velocity_mm_s*mX.velocity_mm_s + mY.velocity_mm_s*mY.velocity_mm_s + mZ.velocity_mm_s*mZ.velocity_mm_s).toFixed(4);

