                rms_y: mY.rms, peak_y: mY.peak, crest_y: mY.crest,
                rms_z: mZ.rms, peak_z: mZ.peak, crest_z: mZ.crest,

                // --- NUEVOS DATOS ---
                kurt_x: mX.kurtosis,
                kurt_y: mY.kurtosis,
                kurt_z: mZ.kurtosis,

                vel_x: mX.velocity_mm_s,
                vel_y: mY.velocity_mm_s,
                vel_z: mZ.velocity_mm_s,
                vel_mag: parseFloat(vel_mag) // <--- ISO 10816 INDICATOR
            },
            timestamp: timestamp
        });
    }

    // Procesar S2 (Igual que S1)
    if (buf.s2_ax.length > 0) {
        var mX2 = calculateComplexMetrics(buf.s2_ax, duration);
        var mY2 = calculateComplexMetrics(buf.s2_ay, duration);
        var mZ2 = calculateComplexMetrics(buf.s2_az, duration);
        var vel_mag2 = Math.sqrt(mX2.velocity_mm_s*mX2.velocity_mm_s + mY2.velocity_mm_s*mY2.velocity_mm_s + mZ2.velocity_mm_s*mZ2.velocity_mm_s).toFixed(4);

