                rms_z: mZ2.rms, peak_z: mZ2.peak, crest_z: mZ2.crest,
                kurt_x: mX2.kurtosis, kurt_y: mY2.kurtosis, kurt_z: mZ2.kurtosis,
                vel_x: mX2.velocity_mm_s, vel_y: mY2.velocity_mm_s, vel_z: mZ2.velocity_mm_s,
                vel_mag: parseFloat(vel_mag2)
            },
            timestamp: timestamp
        });
    }

    // Reset Buffer
    bufferState[nodeId] = { 
        s1_ax:[], s1_ay:[], s1_az:[], 
        s2_ax:[], s2_ay:[], s2_az:[], 
        startTime: Date.now(), // Reiniciamos reloj
