// Ignoramos frecuencias muy bajas (Gravedad/DC)
var MIN_FREQ_HZ = 2.0; 

// --- ALGORITMO FFT (Cooley-Tukey) ---
function fft(amplitudes) {
    var N = amplitudes.length;
    if (N <= 1) return amplitudes;

    var hN = N / 2;
    var even = [];
    var odd = [];

    // Divide (Separar pares e impares)
    for (var i = 0; i < hN; i++) {
        even[i] = amplitudes[2 * i];
        odd[i] = amplitudes[2 * i + 1];
    }

    // Conquer (Recursividad)
    even = fft(even);
    odd = fft(odd);

    var a = -2 * Math.PI;
    var result = new Array(N); 

    // Combine
    for (var k = 0; k < hN; k++) {
        // Multiplicador complejo (Twiddle factor)
        // Nota: Como la entrada es real puros, simplificamos un poco, 
        // pero necesitamos manejo complejo completo para la salida.
        // Aquí asumimos entrada compleja {re, im} para simplificar la recursión.

        // Pero espera, para no complicar con clases complejas en Node-RED,
        // usaremos una implementación iterativa optimizada in-place.
        // (Ver abajo implementation real)
    }
    return []; // Placeholder
}

// --- IMPLEMENTACIÓN ROBUSTA FFT IN-PLACE ---
function runFFT(data) {
    var n = data.length;
    var m = Math.log2(n);

    // Bit-reversal
    var i, j, k;
    var re = new Array(n);
    var im = new Array(n);

    for(i=0; i<n; i++) {
        re[i] = data[i];
        im[i] = 0.0;
    }

    j = 0;
    for (i = 0; i < n - 1; i++) {
        if (i < j) {
            var tr = re[i]; re[i] = re[j]; re[j] = tr;
            var ti = im[i]; im[i] = im[j]; im[j] = ti;
        }
        k = n >> 1;
        while (k <= j) { j -= k; k >>= 1; }
        j += k;
    }

    // Butterfly
    var le, le2, ur, ui, sr, si, tr, ti;
    for (var l = 1; l <= m; l++) {
        le = 1 << l;
        le2 = le >> 1;
        ur = 1.0;
        ui = 0.0;
        sr = Math.cos(Math.PI / le2);
        si = -Math.sin(Math.PI / le2); // FFT Forward

        for (j = 0; j < le2; j++) {
            for (i = j; i < n; i += le) {
                var ip = i + le2;
                tr = re[ip] * ur - im[ip] * ui;
                ti = re[ip] * ui + im[ip] * ur;
                re[ip] = re[i] - tr;
                im[ip] = im[i] - ti;
                re[i] = re[i] + tr;
                im[i] = im[i] + ti;
            }
            tr = ur;
            ur = tr * sr - ui * si;
            ui = tr * si + ui * sr;
        }
    }

    // Calcular Magnitud
    var mags = [];
    // Solo necesitamos la primera mitad (Nyquist)
    for(i=0; i < n/2; i++) {
        mags.push(Math.sqrt(re[i]*re[i] + im[i]*im[i]));
    }
    return mags;
}

// --- PROCESAMIENTO PRINCIPAL ---
var msgData = msg.payload;

