var timeData = msgData.data;
var fs = msgData.fs; // 500 Hz
var N = timeData.length; // 256

// 1. Ejecutar FFT
var magnitudes = runFFT(timeData);

// 2. Mapear Índices a Frecuencias
// Resolución = Fs / N = 500 / 256 = 1.95 Hz por bin
var spectrum = [];
var resolution = fs / N;

for (var i = 0; i < magnitudes.length; i++) {
    var freq = i * resolution;
    // Filtro Pasa Altos (Ignorar DC/Gravedad)
    if (freq > MIN_FREQ_HZ) {
        spectrum.push({ f: parseFloat(freq.toFixed(2)), m: parseFloat(magnitudes[i].toFixed(2)) });
    }
}

// 3. Encontrar los 3 picos más altos
spectrum.sort(function(a, b) { return b.m - a.m; }); // Ordenar descendente por magnitud

var top3 = spectrum.slice(0, 3);

// Si no hay picos (señal plana), rellenar con ceros
while(top3.length < 3) { top3.push({f:0, m:0}); }

