// CONFIGURACIÓN
var WINDOW_SIZE = 50; // Muestras por ventana

// Factor de conversión: 1 G = 9806.65 mm/s²
// Para pasar a mm/s al integrar, usamos este factor.
var G_TO_MM_S2 = 9806.65;

var bufferState = flow.get('sensorBuffer') || {}; 

// --- FUNCIÓN MATEMÁTICA AVANZADA ---
function calculateComplexMetrics(arr, durationSeconds) {
    if (arr.length === 0) return null;

    var n = arr.length;
    var dt = durationSeconds / n; // Tiempo estimado entre cada muestra

    // 1. Estadísticas Básicas (Media, Min, Max)
    var min = Infinity;
    var max = -Infinity;
    var sum = 0;

    for (var i = 0; i < n; i++) {
        var val = arr[i];
        if (val < min) min = val;
        if (val > max) max = val;
        sum += val;
    }
    var mean = sum / n; // Esto representa el componente DC (Gravedad o Offset)

    // 2. Momentos Estadísticos (RMS, Kurtosis)
    var sumSqDiff = 0;   // Para Varianza/RMS AC
    var sum4thDiff = 0;  // Para Kurtosis

    for (var i = 0; i < n; i++) {
        var diff = arr[i] - mean; // Restamos la media para analizar solo la vibración AC
        var sq = diff * diff;
        sumSqDiff += sq;
        sum4thDiff += sq * sq;
    }

    var variance = sumSqDiff / n;
    var stdev = Math.sqrt(variance); // Desviación estándar
    var rms = Math.sqrt((sumSqDiff / n) + (mean*mean)); // RMS Real (incluye DC)

    // Cálculo de Kurtosis (Cuarto momento normalizado)
    // Una onda senoidal pura tiene Kurtosis ~1.5. Golpes suben esto a >3.
    var kurtosis = 0;
    if (variance !== 0) {
        kurtosis = (sum4thDiff / n) / (variance * variance);
    }

    var peak = Math.max(Math.abs(min), Math.abs(max));
    var crestFactor = (rms !== 0) ? (peak / rms) : 0;

    // 3. CÁLCULO DE VELOCIDAD (Integración Numérica)
    // Convertimos Aceleración (G) a Velocidad (mm/s)
    // Usamos integración trapezoidal removiendo el componente DC (Gravedad)
    var velocitySumSq = 0;
    var currentVel = 0;

    for (var i = 0; i < n - 1; i++) {
        // Aceleración en este punto y el siguiente (en G), quitando gravedad (mean)
        var a1 = (arr[i] - mean); 
        var a2 = (arr[i+1] - mean);

        // Área del trapecio = Promedio de altura * base (dt)
        // Resultado en G*s. Multiplicamos por 9806.65 para mm/s
        var area = ((a1 + a2) / 2) * dt * G_TO_MM_S2;

        currentVel += area; // Integramos
        velocitySumSq += currentVel * currentVel;
    }

    // RMS de la Velocidad (El valor que pide la norma ISO 10816)
    var velocityRMS = Math.sqrt(velocitySumSq / (n - 1));

    return {
        rms: parseFloat(rms.toFixed(4)),
        peak: parseFloat(peak.toFixed(4)),
        crest: parseFloat(crestFactor.toFixed(4)),
        kurtosis: parseFloat(kurtosis.toFixed(4)),
        velocity_mm_s: parseFloat(velocityRMS.toFixed(4)) // <--- EL DATO NUEVO
    };
}

