    }
    return []; // Placeholder
}

// --- IMPLEMENTACIÓN ROBUSTA FFT IN-PLACE ---
function runFFT(data) {
    var n = data.length;
    var m = Math.log2(n);

    // Bit-reversal
    var i, j, k;
    var re = new Array(n);
    var im = new Array(n);

    for(i=0; i<n; i++) {
        re[i] = data[i];
        im[i] = 0.0;
    }

    j = 0;
    for (i = 0; i < n - 1; i++) {
        if (i < j) {
            var tr = re[i]; re[i] = re[j]; re[j] = tr;
            var ti = im[i]; im[i] = im[j]; im[j] = ti;
        }
        k = n >> 1;
        while (k <= j) { j -= k; k >>= 1; }
        j += k;
    }

    // Butterfly
    var le, le2, ur, ui, sr, si, tr, ti;
    for (var l = 1; l <= m; l++) {
        le = 1 << l;
        le2 = le >> 1;
        ur = 1.0;
        ui = 0.0;
        sr = Math.cos(Math.PI / le2);
        si = -Math.sin(Math.PI / le2); // FFT Forward

        for (j = 0; j < le2; j++) {
            for (i = j; i < n; i += le) {
                var ip = i + le2;
                tr = re[ip] * ur - im[ip] * ui;
                ti = re[ip] * ui + im[ip] * ur;
                re[ip] = re[i] - tr;
                im[ip] = im[i] - ti;
                re[i] = re[i] + tr;
                im[i] = im[i] + ti;
            }
            tr = ur;
            ur = tr * sr - ui * si;
            ui = tr * si + ui * sr;
        }
    }

    // Calcular Magnitud
    var mags = [];
    // Solo necesitamos la primera mitad (Nyquist)
    for(i=0; i < n/2; i++) {
        mags.push(Math.sqrt(re[i]*re[i] + im[i]*im[i]));
    }
    return mags;
}

